package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.ai.CancellationToken;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.PermissionDecider;
import java.time.Clock;
import java.util.Map;
import java.util.OptionalLong;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

/** Validates permission expiry, cancellation and revision-CAS at the shared application boundary. */
public final class PermissionCoordinator {
    private final PermissionDecider decider;
    private final Clock clock;

    public PermissionCoordinator(PermissionDecider decider, Clock clock) {
        if (decider == null || clock == null) throw new IllegalArgumentException("permission dependencies must not be null");
        this.decider = decider;
        this.clock = clock;
    }

    public CompletableFuture<PermissionDecider.Decision> decide(
            PermissionDecider.Request request, CancellationToken cancellation) {
        if (!clock.instant().isBefore(request.expiresAt())) return failed(ErrorCode.PERMISSION_EXPIRED,
                Map.of("permissionId", request.permissionId()));
        cancellation.throwIfCancellationRequested();
        CompletableFuture<PermissionDecider.Decision> result = new CompletableFuture<>();
        decider.decide(request, cancellation).whenComplete((decision, failure) -> {
            if (failure != null) {
                result.completeExceptionally(unwrap(failure));
                return;
            }
            if (cancellation.isCancellationRequested()) {
                result.completeExceptionally(error(ErrorCode.OPERATION_CANCELLED,
                        Map.of("operationId", request.permissionId())));
                return;
            }
            if (!clock.instant().isBefore(request.expiresAt())) {
                result.completeExceptionally(error(ErrorCode.PERMISSION_EXPIRED,
                        Map.of("permissionId", request.permissionId())));
                return;
            }
            if (!request.permissionId().equals(decision.permissionId())
                    || request.revision() != decision.requestRevision()) {
                result.completeExceptionally(error(ErrorCode.PERMISSION_REVISION_CONFLICT,
                        Map.of("permissionId", request.permissionId(),
                                "expectedRevision", Long.toString(request.revision()),
                                "currentRevision", Long.toString(decision.requestRevision()))));
                return;
            }
            result.complete(decision);
        });
        cancellation.cancellation().thenRun(() -> result.completeExceptionally(error(
                ErrorCode.OPERATION_CANCELLED, Map.of("operationId", request.permissionId()))));
        return result;
    }

    private static <T> CompletableFuture<T> failed(ErrorCode code, Map<String, String> parameters) {
        return CompletableFuture.failedFuture(error(code, parameters));
    }

    private static Throwable unwrap(Throwable failure) {
        return failure instanceof CompletionException && failure.getCause() != null ? failure.getCause() : failure;
    }

    private static JiException error(ErrorCode code, Map<String, String> parameters) {
        return new JiException(new JiError(code, parameters, java.util.Optional.empty(),
                java.util.Optional.empty(), OptionalLong.empty()));
    }
}
